$(errorCatched(() => {

// ═══════════════════════════════════════════════════════════════════
// ★★★ 配置区：所有可调项都在这里，改完保存即生效（酒馆助手保存脚本会重新执行）★★★
// 本脚本不读 settings 文件——循环任务直写 extension_settings 对本脚本无效。
// ═══════════════════════════════════════════════════════════════════

// 总开关：false = 过滤停用（脚本挂载但什么都不做）
const SS_FILTERS_ENABLED = true;

// 跳过标记：prompt 里出现此字符串的那段文本不做过滤；留空 = 不跳过
const SKIP_MARKER = '';

// ── §七 L3 人物屏蔽 ────────────────────────────────────────────────
// 屏蔽名单：命中主体 s 的事实整条删（people 块 / world 行都算）。
// 精确名匹配（NFKC 归一化，全半角/大小写不敏感），不展开别名表；空数组 = 不屏蔽
const SS_BLOCKED_CHARACTERS = ['十一月雨'];

// 完全屏蔽 world 段（主体不在事件参与者字典里的事实整段不注入）
const SS_BLOCK_WORLD = 0;

// 完全屏蔽 people 段（与 blockWorld 可叠加，都开则 [定了的事] 整节消失）
const SS_BLOCK_PEOPLE = false;

// ── §十二 仅保留焦点人物（两级工作方式）───────────────────────────
// 1) 注入文本里有 [焦点人物] 小节（LWB 侧二改区块提供，见剧情总结.txt §二十）
//    时 → 忠实实现：people 块 + world 行都按「主体 ∈ 焦点集」过滤，与原补丁等价；
// 2) 没有时（脚本未更新 / 非向量模式 / 区块被上游冲掉）→ 退化为近似：丢 world: 整段。
const SS_ONLY_KEEP_FOCUS = 0;

// true = [焦点人物] 小节被脚本读取后从 prompt 中删除（模型看不到，与上游行为等价）；
// false = 保留在 prompt 里（模型会看到当前焦点人物名单，一行名字）
const SS_FOCUS_STRIP = true;

// ── §十 事件下方 L0 渲染抑制 ──────────────────────────────────────
// true = [印象深的事]/[其他人的事] 下方不渲染 › #N [📌] 行（含 │ 续行）；
// 零散记忆/新鲜记忆的 L0 不受影响（那里 L0 是唯一呈现）。
// 注意：LWB 代码默认 false（渲染），剧情总结.txt §十 文档写的「默认true」是反的。
const SS_HIDE_L0_UNDER_EVENTS = 0;

// ── §十七 L1 渲染过滤（并集：任一命中即整行删）────────────────────
// 关键词：L1 正文包含任一关键词（大小写不敏感）即删；只匹配正文，不匹配说话人
const SS_L1_FILTER_KEYWORDS = [];

// 楼层：零基楼层号（prompt 里显示 #N 的话这里填 N-1）
const SS_L1_BLOCKED_FLOORS = [];

// 用户侧：true = 删所有 ┌ 开头的用户侧 L1 行
const SS_L1_FILTER_USER = 0;

// ── §十九 弧光人物屏蔽（独立名单，与 SS_BLOCKED_CHARACTERS 互不影响）──
// 只认弧光主体 arc.name（精确名，NFKC 归一化）；moments 里出现的人名不算
const SS_ARC_BLOCKED_CHARACTERS = ['十一月雨'];

// ═══════════════════════════════════════════════════════════════════
// 以下为实现，正常使用不需要动
// ═══════════════════════════════════════════════════════════════════

// 替代 LWB story-summary 源码补丁（剧情总结.txt §七/§十/§十二/§十七/§十九），
// 在最终 prompt 的注入文本上按渲染格式做删除，LWB 侧可回退为上游原版，
// 减少上游同步冲突。与源码补丁的固有差异：
// 1) 发送端过滤发生在 token 预算分配之后：被屏蔽内容已占用本次名额，
//    腾出的预算不会回填其他事实（源码补丁在装箱前过滤，名额可被填上）。
// 2) §十二见上方 SS_ONLY_KEEP_FOCUS 的两级说明。
// 3) 上游若改渲染格式（缩进/标记/小节标题），过滤会静默失配——升级
//    LWB 后行为异常先查这里。

// 配置归一化：trim / 去重 / 类型纠正，容错手改
const SS_CFG = (() => {
  const list = (v) => Array.isArray(v)
    ? [...new Set(v.map((x) => String(x || '').trim()).filter(Boolean))]
    : [];
  return {
    blockedCharacters: list(SS_BLOCKED_CHARACTERS),
    blockWorld: SS_BLOCK_WORLD === true,
    blockPeople: SS_BLOCK_PEOPLE === true,
    onlyKeepFocus: SS_ONLY_KEEP_FOCUS === true,
    focusStrip: SS_FOCUS_STRIP === true,
    hideL0UnderEvents: SS_HIDE_L0_UNDER_EVENTS === true,
    l1Keywords: list(SS_L1_FILTER_KEYWORDS).map((k) => k.toLowerCase()),
    l1BlockedFloors: Array.isArray(SS_L1_BLOCKED_FLOORS)
      ? SS_L1_BLOCKED_FLOORS.map(Number).filter(Number.isInteger)
      : [],
    l1FilterUser: SS_L1_FILTER_USER === true,
    arcBlocked: list(SS_ARC_BLOCKED_CHARACTERS),
  };
})();

// 与 LWB prompt.js / constraint-filter.js 里的 normalize() 逐字等价
const ssNorm = (v) => String(v || '')
  .normalize('NFKC')
  .replace(/[\u200B-\u200D\uFEFF]/g, '')
  .trim()
  .toLowerCase();

// 渲染格式锚点（LWB prompt.js：formatConstraintsStructured / formatEvidenceGroup /
// formatL1Line / formatArcLine，以及二改区块 §二十 的 [焦点人物]）。
// 小节头用全行精确匹配，避免误伤正文里恰好以「[印象深的事]」开头的普通行。
const SS_SECTION_RE = /^\[(定了的事|剧情记忆|角色别名|焦点人物|印象深的事|其他人的事|零散记忆|新鲜记忆|这些人|人物弧光)\]( (已确立的事实|记得很清楚|别人经历的类似事|没归入事件的片段|还没总结的部分|他们的弧光))?$/;
const SS_L0_LINE_RE = /^  › #\d+ \[📌\]/;                        // 事件证据里的 L0 行
const SS_L0_CONT_RE = /^  │/;                                    // L0 长文本续行
const SS_L1_LINE_RE = /^    ([›┌]) #(\d+) \[([^\]]*)\] ?(.*)$/;  // L1 行：符号/楼层/说话人/正文
const SS_PEOPLE_HDR_RE = /^  ([^ ].*):$/;                        // people: 下的「  名字:」块头
const SS_WORLD_LINE_RE = /^  - (.+)$/;                           // world 行「  - 主体 谓词: …」
const SS_ARC_LINE_RE = /^- (.+)$/;                               // 弧光行「- 名字：…」

// world 行主体判断：rest = "主体 谓词: 对象 (#N)"，做「名单前缀 + 空格边界」匹配
const ssIsSubjectHit = (rest, nameSet) => {
  const n = ssNorm(rest);
  for (const b of nameSet) {
    if (b && (n === b || n.startsWith(b + ' '))) return true;
  }
  return false;
};

// L1 行过滤（§十七）：用户侧开关 / 楼层（配置零基，渲染是 floor+1）/ 关键词，任一命中即弃
const ssL1LineDrop = (line, cfg, needL1) => {
  if (!needL1) return false;
  const m = line.match(SS_L1_LINE_RE);
  if (!m) return false;
  if (m[1] === '┌' && cfg.l1FilterUser) return true;
  if (cfg.l1BlockedFloors.includes(Number(m[2]) - 1)) return true;
  if (cfg.l1Keywords.length && m[4]) {
    const t = m[4].toLowerCase();
    if (cfg.l1Keywords.some((k) => t.includes(k))) return true;
  }
  return false;
};

// 预扫描 [焦点人物] 小节（LWB 二改区块 §二十）→ 焦点名单数组；没有该节则返回 null
function ssExtractFocusList(text) {
  let inSection = false;
  const names = [];
  for (const line of String(text).split('\n')) {
    if (line === '[焦点人物]') { inSection = true; continue; }
    if (inSection) {
      if (line === '' || SS_SECTION_RE.test(line)) break;
      for (const part of line.split('、')) {
        const n = String(part || '').trim();
        if (n) names.push(n);
      }
    }
  }
  return inSection && names.length ? names : null;
}

function ssApplyStorySummaryFilters(text, cfg) {
  if (!text) return text;
  // 向量模式：注入体自带 <剧情记忆>…</剧情记忆> 包装，只处理包装区间，
  // 区间外（模板框架文字等）逐字节不动。
  const OPEN = '<剧情记忆>', CLOSE = '</剧情记忆>';
  const openIdx = text.indexOf(OPEN);
  if (openIdx !== -1) {
    const closeIdx = text.indexOf(CLOSE, openIdx + OPEN.length);
    if (closeIdx !== -1) {
      const head = text.slice(0, openIdx + OPEN.length);
      const inner = text.slice(openIdx + OPEN.length, closeIdx);
      const tail = text.slice(closeIdx);
      const focusNames = ssExtractFocusList(inner);
      return head + ssFilterLines(inner, cfg, focusNames) + tail;
    }
  }
  // 非向量模式（无包装，模板直接拼小节）：退化为整段按小节头处理；
  // 消息里连小节头都没有就原样返回。
  if (!text.includes('[定了的事]') && !text.includes('[印象深的事]')
    && !text.includes('[其他人的事]') && !text.includes('[零散记忆]')
    && !text.includes('[新鲜记忆]') && !text.includes('[人物弧光]')
    && !text.includes('[这些人]') && !text.includes('[剧情记忆]')
    && !text.includes('[焦点人物]')) return text;
  const focusNames = ssExtractFocusList(text);
  return ssFilterLines(text, cfg, focusNames);
}

function ssFilterLines(text, cfg, focusNames = null) {
  // §十二：有焦点名单 → 忠实按主体过滤（people 块 + world 行）；
  // 没有名单 → 退化为近似（丢 world: 整段）。
  const focusMode = cfg.onlyKeepFocus && Array.isArray(focusNames) && focusNames.length > 0;
  const focusNorm = focusMode ? new Set(focusNames.map(ssNorm)) : null;
  const dropWorld = cfg.blockWorld || (cfg.onlyKeepFocus && !focusMode);
  const blockedNorm = new Set(cfg.blockedCharacters.map(ssNorm));
  const arcBlockedNorm = new Set(cfg.arcBlocked.map(ssNorm));
  const needL1 = cfg.l1FilterUser || cfg.l1Keywords.length > 0 || cfg.l1BlockedFloors.length > 0;

  const lines = String(text).split('\n');
  const out = [];
  let section = null;        // 当前小节（小节标题行决定）
  let headerPending = null;  // 小节头先挂起：节内有 surviving 行才落，整节删光则连头丢弃
  let subPending = null;     // [定了的事] 内的 'people:' / 'world:' 段头，同样无内容则丢弃
  let mode = null;           // [定了的事] 子状态：'people' | 'world' | null
  let peopleBlocked = false; // 当前 people 块是否被屏蔽/焦点过滤命中

  const emit = (line) => {
    if (headerPending !== null) { out.push(headerPending); headerPending = null; }
    if (subPending !== null) { out.push(subPending); subPending = null; }
    out.push(line);
  };

  for (const line of lines) {
    // 空行：小节头还挂着时，只有「头后自带空行」的小节（事件类）才随头一起落；
    // 其他情况头/段头未落 = 对应段被删光，丢弃；子段挂起而主节已落地时空行保留
    if (line === '') {
      if (headerPending !== null) {
        if (section === '印象深的事' || section === '其他人的事' || section === '剧情记忆') emit(line);
        else { headerPending = null; subPending = null; }
      } else if (subPending !== null) {
        subPending = null;
        out.push(line);
      } else {
        out.push(line);
      }
      continue;
    }

    const hdr = line.match(SS_SECTION_RE);
    if (hdr) { section = hdr[1].split(' ')[0]; mode = null; peopleBlocked = false; headerPending = line; subPending = null; continue; }

    switch (section) {
      case '定了的事': {
        if (line === 'people:' || line === 'world:') {
          mode = line === 'people:' ? 'people' : 'world';
          peopleBlocked = false;
          subPending = line;
          continue;
        }
        if (mode === 'people') {
          const m = line.match(SS_PEOPLE_HDR_RE);
          if (m) {
            // §七 屏蔽名单优先，其次 §十二 焦点过滤（忠实模式）；块内事实一并删
            const subj = ssNorm(m[1].replace(/:$/, ''));
            peopleBlocked = blockedNorm.has(subj) || (focusMode && !focusNorm.has(subj));
          }
          if (peopleBlocked || cfg.blockPeople) continue;
          emit(line); continue;
        }
        if (mode === 'world') {
          if (dropWorld) continue;
          if (blockedNorm.size) {
            const m = line.match(SS_WORLD_LINE_RE);
            if (m && ssIsSubjectHit(m[1], blockedNorm)) continue;
          }
          if (focusMode) {
            const m = line.match(SS_WORLD_LINE_RE);
            if (m && !ssIsSubjectHit(m[1], focusNorm)) continue;
          }
          emit(line); continue;
        }
        emit(line); continue;
      }

      case '焦点人物': {
        // §二十 数据源小节：默认读取后整节删除（头在 headerPending 里自动消失）
        if (cfg.focusStrip) continue;
        emit(line); continue;
      }

      case '印象深的事':
      case '其他人的事':
      case '剧情记忆': {
        if (cfg.hideL0UnderEvents && (SS_L0_LINE_RE.test(line) || SS_L0_CONT_RE.test(line))) continue;
        if (ssL1LineDrop(line, cfg, needL1)) continue;
        emit(line); continue;
      }

      case '零散记忆':
      case '新鲜记忆': {
        if (ssL1LineDrop(line, cfg, needL1)) continue;
        emit(line); continue;
      }

      case '这些人':
      case '人物弧光': {
        if (arcBlockedNorm.size) {
          const m = line.match(SS_ARC_LINE_RE);
          if (m) {
            // §十九：只认弧光主体 arc.name；NFKC 会把全角「：」折成半角「:」，
            // 名单命中 = 归一化后「名字 + 冒号」前缀（moments 里的人名不参与判定）
            const n = ssNorm(m[1]);
            let hit = false;
            for (const b of arcBlockedNorm) {
              if (b && (n === b || n.startsWith(b + '：') || n.startsWith(b + ':'))) { hit = true; break; }
            }
            if (hit) continue;
          }
        }
        emit(line); continue;
      }

      default:
        emit(line);
    }
  }
  return out.join('\n');
}

  eventMakeLast('generate_after_data', (generate_data, dry_run) => {
    // 想让「提示词预览」也生效：把下面这行删掉即可。
    //if (dry_run) return;

    if (!SS_FILTERS_ENABLED) return;

    const filter = (text) => {
      if (SKIP_MARKER && text.includes(SKIP_MARKER)) return text;
      try {
        return ssApplyStorySummaryFilters(text, SS_CFG);
      } catch (e) {
        console.warn('[剧情总结过滤] 出错，本段跳过:', e);
        return text;
      }
    };

    const prompt = generate_data?.prompt;

    // 文本补全类 API（Kobold / TextGen / Novel）：整个 prompt 是字符串
    if (typeof prompt === 'string') {
      generate_data.prompt = filter(prompt);
      return;
    }

    // chat 补全类 API（OpenAI 系）：prompt 是消息数组
    if (Array.isArray(prompt)) {
      for (const msg of prompt) {
        if (!msg?.content) continue;
        if (typeof msg.content === 'string') {
          msg.content = filter(msg.content);
        } else if (Array.isArray(msg.content)) {
          // 多模态内容（图片 + 文字）只处理其中的文本部分
          msg.content
            .filter((part) => part?.type === 'text')
            .forEach((part) => { part.text = filter(part.text); });
        }
      }
    }
  });

}));
